      "analogy_mapping": [
        {
          "inspiration": "Inverse Problems and Data Assimilation",
          "concept": "Hidden-state inverse estimation from sparse noisy observations using physical forward models and regularization",
          "adaptation": "Formulate microscopic interface measurement as an inverse problem that recovers hidden interfacial flux-force coefficients and fields from multimodal optical, electrical, and flow observations.",
